// Prefix-based annotations cannot leak into a different move order or variation.
export const annotations=[];
const add=(pgn,why,threat,ignore)=>annotations.push({line:pgn.split(' '),why,threat,ignore});
add('e4','e4/d5 공간을 통제하고 f1 비숍·퀸의 길을 엽니다. Nf3의 길은 원래 열려 있습니다.','즉시 강제 위협보다 중앙과 전개 기반을 만듭니다.','중앙에 대응하지 않으면 d4를 추가한 넓은 공간을 허용할 수 있습니다.');
add('d4','d4/e5를 통제하고 c1 비숍의 길을 엽니다. 퀸이 d4를 지켜 e4와 다른 안정성이 있습니다.','중앙 공간 구축이며 당장 폰을 얻는 위협은 아닙니다.','백이 c4/e4로 중앙을 더 넓힐 가능성을 확인해야 합니다.');
add('e4 e5','흑도 중앙을 직접 점유해 대칭적인 열린 게임의 기반을 만듭니다.','d4 전진을 견제합니다.','백 Nf3가 e5를 공격하므로 다음 수에 수비나 e4 반격을 준비합니다.');
add('e4 c5','d4를 측면에서 통제하고 e5 대칭을 피합니다. c폰과 d폰을 교환하면 흑이 반열린 c열을 얻습니다.','d4가 나오면 …cxd4로 비대칭 중앙을 만들 수 있습니다.','백이 중앙을 넓혀도 곧바로 실패한 수는 아닙니다. 이후 반격과 전개를 이어가야 합니다.');
add('e4 e6','…d5를 지지할 폰을 두지만 c8 비숍의 길을 제한합니다.','다음 …d5로 e4에 도전할 준비입니다.','백 d4를 허용한 뒤 중앙 반격 없이 기다리면 공간이 줄어듭니다.');
add('e4 c6','…d5를 c폰으로 받쳐 e4를 교환하고 비숍을 먼저 꺼낼 여지를 남깁니다.','…d5 중앙 반격을 준비합니다.','전개 지연을 …d5와 연결하지 않으면 백이 자유롭게 중앙을 확장합니다.');
add('e4 d5','e4폰을 바로 공격해 중앙을 명확히 교환하려 합니다.','…dxe4로 중앙 폰을 잡을 수 있습니다.','백은 중앙 유지·교환을 결정해야 하며 다른 수를 두면 e4가 잡힐 수 있습니다.');
add('e4 Nf6','나이트로 e4를 공격해 백 폰을 전진시키고 나중에 그 중앙을 압박하려 합니다.','…Nxe4가 가능할 수 있습니다.','백은 e5·수비·교환형 선택을 해야 하며 e4를 무방비로 두지 않습니다.');
add('d4 Nf6','e4를 기물로 통제하고 중앙 폰 선택을 미룹니다.','백의 즉각적인 무지원 e4를 견제합니다.','c4/Nc3 뒤에는 …e6·…g6·…d5 중 실제 구조를 선택해야 합니다.');
add('d4 f5','e4를 폰으로 통제하고 왕측 공간을 얻는 대신 킹 대각선을 약하게 합니다.','중앙 e4 확장을 견제합니다.','전개와 킹 안전 없이 공격만 하면 약한 대각선이 전술 표적이 됩니다.');
add('e4 e5 Nf3','e5를 공격하며 왕측 나이트를 전개하고 캐슬링을 준비합니다.','Nxe5의 가능성으로 흑의 응수를 제한합니다.','흑은 e5 수비 또는 …Nf6의 e4 반격을 준비해야 합니다.');
add('e4 e5 Nc3','e4를 지키고 d5를 통제하면서 f폰을 움직일 선택을 남깁니다.','즉시 강제 위협은 없으며 중앙 수비·전개가 목적입니다.','흑은 전개와 중앙 반격을 하며 f4 가능성을 확인합니다.');
add('e4 e5 Nc3 Nf6 f4','e5를 공격해 중앙 사슬과 f열 활동을 바꾸려 합니다. 킹 주변 약화가 비용입니다.','fxe5 가능성과 중앙 확장을 준비합니다.','흑은 …d5 중앙 반격을 검토합니다. 단순 수락 …exf4에는 e5 템포 공격이 있습니다.');
add('e4 e5 Nc3 Nf6 f4 d5','측면 f4 공격에 중앙에서 대응하고 e4를 공격합니다.','…dxe4와 중앙 전술이 생깁니다.','백이 왕측만 공격하면 중앙 폰 손실·열린 킹 선이 먼저 생길 수 있습니다.');
add('e4 e5 Nc3 Nf6 f4 exf4 e5','e5폰으로 f6 나이트를 공격해 전개 템포를 얻습니다.','exf6으로 나이트를 잡을 수 있습니다.','흑은 나이트의 합법적인 퇴로와 중앙 대응을 계산해야 합니다.');
add('e4 e5 Nf3 Nc6 Bc4','c4 비숍은 d5와 f7을 겨냥하며 캐슬링을 준비합니다.','f7 압력은 있지만 비숍 하나만으로 강제 메이트는 아닙니다.','흑은 전개와 …d5 반격을 준비하고 Ng5 등 추가 공격의 조건을 살핍니다.');
add('e4 e5 Nf3 Nc6 Bb5','e5를 지키는 c6 나이트를 압박합니다.','Bxc6 뒤 중앙 압력 가능성이 있지만 e5가 당장 공짜는 아닙니다.','흑은 중앙 수비와 전개를 연결합니다. 교환 후 퀸의 중앙 반격도 계산해야 합니다.');
add('e4 e5 Nf3 Nc6 d4','e5 수비를 직접 시험하고 중앙을 열어 빠른 기물 활동을 얻습니다.','dxe5와 중앙 교환이 가능합니다.','흑은 중앙을 교환하거나 지켜야 하며 열린 선의 킹 안전을 확인합니다.');
add('e4 c5 Nf3 d6 d4','흑 c폰과 교환해 공간·d4 나이트 활동을 얻습니다.','dxc5 또는 중앙 긴장 변화가 생깁니다.','흑이 중앙 반격을 놓치면 백 공간이 더 커질 수 있습니다.');
add('e4 c5 Nf3 d6 d4 cxd4','c폰을 d폰과 교환해 흑 반열린 c열과 중앙 폰 다수를 만듭니다.','백은 폰 회복 수단을 준비해야 합니다.','백이 되잡기를 미루면 다른 갬빗/전개 구조가 되어 계획도 달라집니다.');
add('e4 e6 d4 d5 e5','공간을 얻고 d4–e5 사슬로 중앙을 닫습니다.','당장 강제 공격보다 왕측 기물 배치의 공간이 목적입니다.','흑은 …c5로 d4를 공격하거나 …f6를 준비해 공간을 줄입니다.');
add('e4 e6 d4 d5 e5 c5','백 사슬의 밑부분 d4를 공격합니다.','…cxd4로 지지 기반을 제거할 수 있습니다.','백이 d4 수비를 놓치면 e5의 공간 거점도 유지하기 어려워집니다.');
add('e4 c6 d4 d5 e5 Bf5','…e6 전에 밝은 칸 비숍을 사슬 밖으로 꺼냅니다.','직접 재료 위협보다 이후 비숍 제한을 피하는 전략 수입니다.','백은 비숍 압박과 중앙 수비를 함께 준비하며 폰 전진의 킹 약화도 계산합니다.');
add('d4 d5 c4','c폰으로 흑 d5를 공격해 중앙 공간 또는 유리한 교환 구조를 얻으려 합니다.','cxd5로 중앙 수비를 바꿀 수 있습니다.','흑은 수락·거절·슬라브 등의 방식으로 중앙 구조를 선택해야 합니다.');
add('d4 Nf6 c4 e6 Nc3 Bb4','c3 나이트를 핀해 백의 e4 중앙 확장을 견제합니다.','…Bxc3로 구조를 바꿀 수 있지만 강제는 아닙니다.','백은 핀 해소와 되잡기 선택을 확인해야 합니다. b폰으로 되잡으면 더블폰과 열린 b열이 생깁니다.');
add('d4 Nf6 c4 g6 Nc3 d5','백 중앙을 초기에 공격해 킹스 인디언과 다른 교환 구조를 만듭니다.','…dxc4와 중앙 교환이 가능합니다.','백은 중앙 유지·교환을 고르고 큰 중앙을 얻더라도 이후 …c5 압박을 준비해야 합니다.');
add('e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 a6','Nb5/Bb5를 통제하고 …b5 확장을 준비합니다.','즉시 폰 획득보다 퀸측 공간과 중앙 선택을 지지합니다.','백은 …b5·…e5/…e6에 맞춰 배치합니다. 모든 나이도프가 같은 폰 구조는 아닙니다.');
add('e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 a6 Be3 e5','d4 나이트를 공격하며 공간을 얻지만 d5 구멍을 감수합니다.','…exd4로 나이트를 잡을 수 있습니다.','백은 나이트를 이동하고 d5 전초기지·d6 약점을 장기 표적으로 봅니다.');
add('e4 c5 Nf3 Nc6 d4 cxd4 Nxd4 Nf6 Nc3 e5','d4 나이트를 밀며 활동을 얻고 d5·d6 약점을 받아들입니다.','…exd4로 나이트를 잡을 수 있습니다.','백은 나이트 퇴로와 d5 통제를 선택해야 합니다.');
add('e4 c5 Nf3 Nc6 d4 cxd4 Nxd4 g6 c4','c4/e4 두 폰으로 d5를 통제해 흑의 한 번에 …d5 돌파를 억제합니다.','즉시 강제 위협보다 장기 공간 봉쇄입니다.','흑은 기물 교환과 …b5/…d5 준비로 공간 부족을 해결해야 합니다.');
add('d4 Nf6 c4 c5 d5 b5','b폰을 희생해 a/b열의 장기 압박을 준비합니다.','…bxc4가 중앙 지지 폰을 없앨 수 있습니다.','백은 수락·거절을 선택해야 하며 폰을 잡으면 열린 퀸측 열을 방어할 과제가 생깁니다.');
add('e4 e5 Nf3 Nc6 Bc4 Nf6 Ng5 d5 exd5 Nxd5 Nxf7','f7에서 나이트를 희생해 흑 킹을 중앙으로 끌어냅니다. 이 …Nxd5 배치에 한정한 전술입니다.','퀸과 h8 룩을 포크하고 …Kxf7 뒤 Qf3+가 이어집니다.','흑이 잡든 피하든 재료·체크를 구체적으로 계산해야 합니다. 5…Na5에는 같은 희생을 자동 적용하지 않습니다.');
